/**
 * Zet Montserrat klaar in een jsPDF-document. Idempotent: een tweede aanroep op
 * hetzelfde document doet niets.
 */
export function registreerMontserrat(doc: jsPDF): void {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const d = doc as any
  if (d.__montserrat) return
  for (const v of VARIANTEN) {
    doc.addFileToVFS(v.naam, v.b64)
    doc.addFont(v.naam, 'Montserrat', v.stijl)
  }
  d.__montserrat = true
}
